const CODE_IV = `#include <algorithm>
#include <bit>
#include <cstdio>
#include <functional>
#include <random>
#include <vector>

struct Interval { int start, finish; };  // half-open [start, finish)

// Greedy: sort by finish time, take every interval that starts after the last pick ends.
int earliestFinish(std::vector<Interval> v) {
    std::sort(v.begin(), v.end(),
              [](const Interval& a, const Interval& b) { return a.finish < b.finish; });
    int count = 0, lastFinish = -1'000'000;
    for (const auto& x : v)
        if (x.start >= lastFinish) {  // compatible with everything chosen so far
            ++count;
            lastFinish = x.finish;
        }
    return count;
}

// Same loop, but a different (wrong) greedy rule chooses the order.
int greedyBy(std::vector<Interval> v, std::function<bool(const Interval&, const Interval&)> before) {
    std::stable_sort(v.begin(), v.end(), before);  // ties keep input order
    std::vector<Interval> chosen;
    for (const auto& x : v) {
        bool ok = true;
        for (const auto& c : chosen) ok = ok && (x.finish <= c.start || c.finish <= x.start);
        if (ok) chosen.push_back(x);
    }
    return int(chosen.size());
}

// Exhaustive search over all 2^n subsets (small n only).
int bruteForce(const std::vector<Interval>& v) {
    const int n = int(v.size());
    int best = 0;
    for (int mask = 0; mask < (1 << n); ++mask) {
        bool ok = true;
        for (int i = 0; i < n && ok; ++i)
            for (int j = i + 1; j < n && ok; ++j)
                if ((mask >> i & 1) && (mask >> j & 1))
                    ok = v[i].finish <= v[j].start || v[j].finish <= v[i].start;
        if (ok) best = std::max(best, std::popcount(unsigned(mask)));
    }
    return best;
}

int main() {
    std::vector<Interval> demo = {{1, 3}, {2, 4}, {3, 5}, {0, 6}, {4, 7}, {5, 8}, {7, 9}, {6, 9}};
    std::printf("demo: earliest finish picks %d, optimum %d\\n", earliestFinish(demo), bruteForce(demo));

    std::mt19937 rng(7);
    int trials = 2000, finishOk = 0, startOk = 0, shortOk = 0;
    for (int t = 0; t < trials; ++t) {
        std::vector<Interval> v(10);
        for (auto& x : v) {
            x.start = int(rng() % 20);
            x.finish = x.start + 1 + int(rng() % 8);
        }
        int opt = bruteForce(v);
        finishOk += earliestFinish(v) == opt;
        startOk += greedyBy(v, [](auto& a, auto& b) { return a.start < b.start; }) == opt;
        shortOk += greedyBy(v, [](auto& a, auto& b) {
                       return a.finish - a.start < b.finish - b.start; }) == opt;
    }
    std::printf("optimal on %d random instances of 10 intervals:\\n", trials);
    std::printf("  earliest finish:   %d\\n  earliest start:    %d\\n  shortest interval: %d\\n",
                finishOk, startOk, shortOk);
}`;
