const CODE_KS = `#include <algorithm>
#include <cstdio>
#include <vector>

struct Item { const char* name; int weight, value; };

// Fractional knapsack: sort by value density, take greedily, split the last item.
double fractional(std::vector<Item> items, int capacity) {
    std::stable_sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
        return a.value * b.weight > b.value * a.weight;  // a.v/a.w > b.v/b.w without division
    });
    double total = 0;
    int room = capacity;
    for (const auto& it : items) {
        if (room == 0) break;
        int take = std::min(room, it.weight);
        total += double(it.value) * take / it.weight;
        std::printf("  take %d/%d of %s\\n", take, it.weight, it.name);
        room -= take;
    }
    return total;
}

// The same greedy order for 0/1 items: take an item only if it fits whole.
int greedy01(std::vector<Item> items, int capacity) {
    std::stable_sort(items.begin(), items.end(), [](const Item& a, const Item& b) {
        return a.value * b.weight > b.value * a.weight;
    });
    int total = 0;
    for (const auto& it : items)
        if (it.weight <= capacity) { capacity -= it.weight; total += it.value; }
    return total;
}

// Exact 0/1 answer by trying every subset (fine for a handful of items).
int best01(const std::vector<Item>& items, int capacity) {
    int best = 0, n = int(items.size());
    for (int mask = 0; mask < (1 << n); ++mask) {
        int w = 0, v = 0;
        for (int i = 0; i < n; ++i)
            if (mask >> i & 1) { w += items[i].weight; v += items[i].value; }
        if (w <= capacity) best = std::max(best, v);
    }
    return best;
}

int main() {
    std::vector<Item> items = {{"A", 6, 30}, {"B", 5, 20}, {"C", 5, 20}};
    const int capacity = 10;
    std::printf("fractional:\\n");
    double f = fractional(items, capacity);
    std::printf("  value %.1f\\n", f);
    std::printf("0/1 greedy by density: %d\\n", greedy01(items, capacity));
    std::printf("0/1 optimum:           %d\\n", best01(items, capacity));
}`;
