const CODE_COINS = `#include <algorithm>
#include <climits>
#include <cstdio>
#include <vector>

// Greedy change-making: always take the largest coin that fits.
int greedyCoins(const std::vector<int>& coins, int amount) {  // coins sorted ascending
    int count = 0;
    for (int i = int(coins.size()) - 1; i >= 0; --i) {
        count += amount / coins[i];
        amount %= coins[i];
    }
    return count;
}

// Exact minimum by dynamic programming (the DP unit explains this in depth).
std::vector<int> minCoins(const std::vector<int>& coins, int maxAmount) {
    std::vector<int> best(maxAmount + 1, INT_MAX);
    best[0] = 0;
    for (int a = 1; a <= maxAmount; ++a)
        for (int c : coins)
            if (c <= a && best[a - c] != INT_MAX) best[a] = std::min(best[a], best[a - c] + 1);
    return best;
}

int main() {
    const std::vector<std::vector<int>> systems = {{1, 5, 10, 25}, {1, 3, 4}, {1, 10, 25}, {1, 2, 5, 10, 20, 50}};
    for (const auto& coins : systems) {
        std::vector<int> best = minCoins(coins, 100);
        int firstBad = -1, bad = 0;
        for (int a = 1; a <= 100; ++a)
            if (greedyCoins(coins, a) != best[a]) {
                ++bad;
                if (firstBad == -1) firstBad = a;
            }
        std::printf("{");
        for (size_t i = 0; i < coins.size(); ++i) std::printf(i ? ", %d" : "%d", coins[i]);
        if (bad == 0) std::printf("}: greedy optimal for every amount up to 100\\n");
        else std::printf("}: greedy wrong for %d amounts up to 100; first is %d (greedy %d coins, best %d)\\n",
                         bad, firstBad, greedyCoins(coins, firstBad), best[firstBad]);
    }
}`;
const OUT_COINS = `{1, 5, 10, 25}: greedy optimal for every amount up to 100
{1, 3, 4}: greedy wrong for 24 amounts up to 100; first is 6 (greedy 3 coins, best 2)
{1, 10, 25}: greedy wrong for 30 amounts up to 100; first is 30 (greedy 6 coins, best 3)
{1, 2, 5, 10, 20, 50}: greedy optimal for every amount up to 100`;
const CODE_HUF = `#include <cstdio>
#include <functional>
#include <queue>
#include <string>
#include <utility>
#include <vector>

// Nodes live in one vector and refer to children by index (no new/delete).
struct Node {
    long long weight;
    char symbol;  // leaves only
    int left = -1, right = -1;  // left = bit 0, right = bit 1
};

void assignCodes(const std::vector<Node>& t, int n, const std::string& prefix,
                 std::vector<std::string>& code) {
    if (t[n].left == -1) {  // a leaf: the path from the root is its code
        code[(unsigned char)t[n].symbol] = prefix.empty() ? "0" : prefix;
        return;
    }
    assignCodes(t, t[n].left, prefix + '0', code);
    assignCodes(t, t[n].right, prefix + '1', code);
}

int main() {
    const std::string symbols = "ABCDEFG";
    const std::vector<long long> freq = {20, 8, 6, 15, 30, 5, 16};

    std::vector<Node> tree;
    using Item = std::pair<long long, int>;  // (weight, node index)
    std::priority_queue<Item, std::vector<Item>, std::greater<>> pq;  // min-heap
    for (size_t i = 0; i < symbols.size(); ++i) {
        tree.push_back({freq[i], symbols[i]});
        pq.push({freq[i], int(i)});
    }

    long long sumOfMerges = 0;
    while (pq.size() > 1) {
        auto [wx, x] = pq.top(); pq.pop();  // the two lightest subtrees
        auto [wy, y] = pq.top(); pq.pop();
        tree.push_back({wx + wy, 0, x, y});
        pq.push({wx + wy, int(tree.size()) - 1});
        sumOfMerges += wx + wy;  // one more bit for every symbol under this node
        std::printf("merge %lld + %lld -> %lld\\n", wx, wy, wx + wy);
    }

    std::vector<std::string> code(256);
    assignCodes(tree, pq.top().second, "", code);
    long long bits = 0, count = 0;
    for (size_t i = 0; i < symbols.size(); ++i) {
        const std::string& c = code[(unsigned char)symbols[i]];
        std::printf("%c  freq %2lld  code %s\\n", symbols[i], freq[i], c.c_str());
        bits += freq[i] * (long long)c.size();
        count += freq[i];
    }
    std::printf("total bits %lld = sum of merges %lld; a fixed 3-bit code needs %lld\\n",
                bits, sumOfMerges, 3 * count);
}`;
const OUT_HUF = `merge 5 + 6 -> 11
merge 8 + 11 -> 19
merge 15 + 16 -> 31
merge 19 + 20 -> 39
merge 30 + 31 -> 61
merge 39 + 61 -> 100
A  freq 20  code 01
B  freq  8  code 000
C  freq  6  code 0011
D  freq 15  code 110
E  freq 30  code 10
F  freq  5  code 0010
G  freq 16  code 111
total bits 261 = sum of merges 261; a fixed 3-bit code needs 300`;

